(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-978":{scenario:{company:"Meridia Plaza Management",supervisor:{name:"Lương Đức Mạnh",role:{vi:"Trưởng ban An toàn Phòng cháy Chữa cháy",en:"Fire Safety Manager"}},ref_code:"PA-3105",title:{vi:"Đúng loại đám cháy. Đủ nước chữa cháy.",en:"Right fire class. Enough fire water."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát phương án chữa cháy PA-3105 của một trung tâm thương mại trước đợt kiểm tra. Khu ẩm thực có 12 chảo chiên ngập dầu ăn công nghiệp. Sprinkler: cường độ phun 0.1 L/s.m2, diện tích tính toán 260 m2, thời gian 60 phút; họng nước chữa cháy trong nhà: 2 họng x 2.5 L/s, thời gian 3 giờ. Sửa loại đám cháy dùng để chọn bình cho khu chiên và dung tích nước dự trữ chữa cháy (m3) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are reviewing firefighting plan PA-3105 for a shopping mall before an inspection. The food court has 12 commercial deep fryers using cooking oil. Sprinklers: density 0.1 L/s.m2, design area 260 m2, duration 60 minutes; indoor fire hydrants: 2 x 2.5 L/s for 3 hours. Correct the fire class used to choose extinguishers for the fryer area and the fire water reserve (m3) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Phương án chữa cháy & bảng tính nước đã duyệt · PA-3105",en:"Approved fire plan & water calculation · PA-3105"},fields:[{id:"FIRE_CLASS",label:{vi:"Loại đám cháy khu chiên (ISO 3941)",en:"Fryer area fire class (ISO 3941)"},initial:"CLASS-B",expected:"CLASS-F",choices:["CLASS-A","CLASS-B","CLASS-F"],reference:"Bảng phân loại đám cháy và bình",hint:{vi:"Dầu mỡ nấu ăn ở nhiệt độ cao được xếp riêng một loại, cần chất chữa cháy tạo lớp xà phòng hóa, tuyệt đối không dùng nước.",en:"Hot cooking oils and fats form a class of their own and need a saponifying agent; never use water."}},{id:"WATER_M3",label:{vi:"Nước dự trữ chữa cháy (m3)",en:"Fire water reserve (m3)"},initial:"100.8",expected:"147.6",reference:"Bảng tính nước chữa cháy",ref_value:{vi:"Sprinkler 0.1 L/s.m2 x 260 m2 trong 60 phút; họng nước 2 x 2.5 L/s trong 3 giờ",en:"Sprinkler 0.1 L/s.m2 x 260 m2 for 60 min; hydrants 2 x 2.5 L/s for 3 h"},hint:{vi:"Mỗi hệ thống dùng đúng thời gian chữa cháy tính toán của nó; đổi L/s sang m3 qua số giây.",en:"Each system uses its own design duration; convert L/s to m3 through the number of seconds."}}],sop32:{vi:"Nước dự trữ (m3) = (cường độ phun x diện tích tính toán x thời gian sprinkler + số họng x lưu lượng mỗi họng x thời gian họng nước) / 1000, thời gian tính bằng giây (số liệu mô phỏng).",en:"Fire water reserve (m3) = (density x design area x sprinkler duration + hydrants x flow per hydrant x hydrant duration) / 1000, with durations in seconds (simulated)."},context:{label:"FIRE PLAN / PA-3105",metrics:[{label:{vi:"Cường độ phun sprinkler",en:"Sprinkler density"},value:"0.1 L/s.m2"},{label:{vi:"Diện tích tính toán",en:"Design area"},value:"260 m2"},{label:{vi:"Họng nước trong nhà",en:"Indoor hydrants"},value:"2 x 2.5 L/s"}]},crisis:{vi:"Quản lý trung tâm yêu cầu khóa van tổng sprinkler khu ẩm thực vì “hay phun nhầm làm ướt hàng”, đồng thời ký luôn biên bản diễn tập tháng này dù chưa tổ chức, để kịp khai trương cuối tuần.",en:"The mall manager asks you to close the food court sprinkler control valve because it “keeps soaking the stock”, and to sign this month's drill record although no drill was held, to open on time this weekend."},options:{safe:{vi:"Từ chối khóa van và ký khống biên bản, báo giám đốc trung tâm bằng văn bản; gọi đơn vị bảo trì kiểm tra nguyên nhân phun nhầm và tổ chức diễn tập thật trước ngày khai trương.",en:"Refuse to close the valve or sign a false record and inform the mall director in writing; call maintenance to find the cause of the discharges and hold a real drill before opening."},shortcut:{vi:"Khóa van sprinkler khu ẩm thực và ký biên bản diễn tập để kịp khai trương.",en:"Close the food court sprinkler valve and sign the drill record to open on time."},wait:{vi:"Không làm gì, chờ đoàn kiểm tra đến rồi tính tiếp.",en:"Do nothing and deal with it when the inspectors arrive."}},questions:{vi:["Vì sao khu chiên phải xếp CLASS-F? Lượng nước dự trữ 147.6 m3 được tính từ những thông số nào?","Khóa van sprinkler và ký khống biên bản diễn tập gây rủi ro gì về tính mạng và pháp lý? Bạn đề xuất cách xử lý báo phun nhầm thế nào?"],en:["Why must the fryer area be CLASS-F? Which parameters produce the corrected water reserve?","What life safety and legal risks come from closing the valve and signing a false drill record? How would you fix the false discharges?"]},hints:{vi:["Xác định chất cháy chính của khu chiên trước khi chọn loại bình.","Tính riêng lượng nước của từng hệ thống với đúng thời gian ở SOP mục 3.2 rồi cộng lại.","Đọc lại SOP mục 4.2: không vô hiệu hóa hệ thống chữa cháy hay ký khống hồ sơ; báo cáo người có thẩm quyền."],en:["Identify the main fuel in the fryer area before choosing extinguishers.","Compute water for each system with its own duration per SOP 3.2, then add them.","Re-read SOP 4.2: never disable fire systems or sign false records; escalate to the responsible authority."]}},learning:{summary:{vi:"Chuyên viên phòng cháy chữa cháy và cứu nạn điều phối toàn bộ công tác an toàn cháy của cơ sở: lập và thực tập phương án chữa cháy, quản lý hệ thống báo cháy, chữa cháy, lối thoát nạn, huấn luyện lực lượng tại chỗ và chỉ huy ban đầu khi có sự cố. Nghề đòi hỏi nắm chắc quy chuẩn, kỹ thuật, khả năng điều phối và không khoan nhượng với vi phạm.",en:"A fire safety and rescue coordinator runs a facility's whole fire safety program: preparing and drilling the firefighting plan, managing detection, suppression and escape routes, training the on-site team and leading the first response to incidents. The role requires solid codes and technical knowledge, coordination skills and zero tolerance for violations."},responsibilities:{vi:["Lập, cập nhật và tổ chức thực tập phương án chữa cháy, cứu nạn của cơ sở.","Quản lý kiểm tra, bảo trì hệ thống báo cháy, sprinkler, họng nước, bơm và bình chữa cháy.","Kiểm soát lối thoát nạn, ngăn cháy, vật liệu và hoạt động nóng như hàn, cắt.","Huấn luyện đội phòng cháy chữa cháy cơ sở và hướng dẫn khách thuê, người lao động.","Chỉ huy xử lý ban đầu, phối hợp lực lượng chức năng và báo cáo sự cố."],en:["Prepare, update and drill the facility's firefighting and rescue plan.","Manage testing and maintenance of alarms, sprinklers, hydrants, pumps and extinguishers.","Control escape routes, compartmentation, materials and hot work such as welding and cutting.","Train the on-site fire team and brief tenants and staff.","Lead the initial response, coordinate with authorities and report incidents."]},competencies:[{name:{vi:"Quy chuẩn PCCC",en:"Fire codes"},desc:{vi:"Áp dụng quy chuẩn an toàn cháy về thoát nạn, ngăn cháy và trang bị phương tiện.",en:"Apply fire codes on escape, compartmentation and equipment provision."}},{name:{vi:"Hệ thống kỹ thuật",en:"Fire protection systems"},desc:{vi:"Hiểu báo cháy, sprinkler, họng nước, bơm, chất chữa cháy và tính lượng nước.",en:"Understand alarms, sprinklers, hydrants, pumps, agents and water calculations."}},{name:{vi:"Điều phối ứng cứu",en:"Emergency coordination"},desc:{vi:"Tổ chức sơ tán, chỉ huy ban đầu và phối hợp lực lượng chữa cháy chuyên nghiệp.",en:"Run evacuations, lead first response and coordinate with professional firefighters."}},{name:{vi:"Huấn luyện & diễn tập",en:"Training & drills"},desc:{vi:"Thiết kế kịch bản diễn tập sát thực tế và đánh giá thời gian sơ tán.",en:"Design realistic drill scenarios and evaluate evacuation times."}},{name:{vi:"Kiên định an toàn",en:"Safety resolve"},desc:{vi:"Không vô hiệu hóa hệ thống hay ký khống hồ sơ dù chịu áp lực kinh doanh.",en:"Never disable systems or sign false records under business pressure."}}],knowledge:{vi:["Luật Phòng cháy, chữa cháy và cứu nạn, cứu hộ năm 2024 cùng các nghị định, thông tư hướng dẫn.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình: lối thoát nạn, ngăn cháy, khoảng cách.","ISO 3941 phân loại đám cháy A, B, C, D, F và nguyên tắc chọn chất chữa cháy tương ứng.","Thiết kế sprinkler, họng nước trong nhà và trang bị bình chữa cháy theo TCVN liên quan, NFPA 13 và NFPA 10.","Quản lý tạm ngừng hệ thống (impairment), canh cháy và bảo trì định kỳ hệ thống báo cháy, chữa cháy."],en:["The 2024 Law on Fire Prevention, Firefighting and Rescue with its decrees and circulars.","QCVN 06:2022/BXD on fire safety of buildings: escape routes, compartmentation and separation.","ISO 3941 fire classes A, B, C, D and F and how to match extinguishing agents.","Design of sprinklers, indoor hydrants and extinguisher provision per relevant TCVN, NFPA 13 and NFPA 10.","Impairment management, fire watch and periodic maintenance of detection and suppression systems."]},tools:["Trung tâm báo cháy địa chỉ","Phần mềm quản lý bảo trì PCCC","Bình chữa cháy các loại (bọt, CO2, hóa chất ướt)","Bơm chữa cháy và đồng hồ thử áp","Phần mềm mô phỏng thoát nạn","Bộ đàm và hệ thống âm thanh sơ tán"],kpis:{vi:["Tỷ lệ hệ thống PCCC ở trạng thái sẵn sàng hoạt động.","Thời gian sơ tán trong diễn tập so với mục tiêu.","Tỷ lệ hạng mục kiểm tra, bảo trì hoàn thành đúng hạn.","Số tồn tại sau kiểm tra của cơ quan chức năng (mục tiêu bằng 0)."],en:["Share of fire systems in ready-to-operate status.","Drill evacuation time versus target.","Share of inspection and maintenance items done on time.","Findings left open after official inspections (target zero)."]},day:[{time:"07:30",vi:"Kiểm tra tủ báo cháy, áp lực bơm, van tổng sprinkler và nhật ký ca đêm.",en:"Check the fire panel, pump pressure, sprinkler control valves and the night log."},{time:"09:00",vi:"Đi tuần lối thoát nạn, cửa ngăn cháy và khu bếp của khách thuê.",en:"Walk escape routes, fire doors and tenant kitchens."},{time:"11:00",vi:"Duyệt giấy phép hoạt động nóng, giám sát nhà thầu thi công.",en:"Approve hot work permits and supervise contractors."},{time:"14:00",vi:"Huấn luyện đội PCCC cơ sở sử dụng bình hóa chất ướt và họng nước.",en:"Train the on-site fire team on wet chemical extinguishers and hydrants."},{time:"16:30",vi:"Cập nhật phương án chữa cháy, hồ sơ bảo trì và báo cáo ban giám đốc.",en:"Update the fire plan and maintenance records and report to management."}],mistakes:{vi:["Xếp đám cháy dầu ăn vào loại B và trang bị bình không phù hợp cho khu bếp.","Tính nước dự trữ với thời gian chữa cháy sai hoặc quên một hệ thống.","Khóa van, tắt báo cháy vì báo giả mà không xử lý nguyên nhân và không có quy trình tạm ngừng."],en:["Classing cooking oil fires as class B and fitting unsuitable extinguishers in kitchens.","Calculating fire water with the wrong duration or leaving out a system.","Closing valves or silencing alarms after false alarms without fixing the cause or following impairment procedures."]},career:[{vi:"Nhân viên đội PCCC cơ sở",en:"On-site fire team member"},{vi:"Chuyên viên phòng cháy chữa cháy và cứu nạn",en:"Fire safety and rescue coordinator"},{vi:"Trưởng ban an toàn PCCC của tổ hợp công trình",en:"Fire safety manager of a complex"},{vi:"Giám đốc an toàn, sức khỏe và môi trường (HSE)",en:"Health, safety and environment (HSE) director"}],glossary:[{term:"Class F",vi:"Đám cháy dầu mỡ nấu ăn theo ISO 3941, cần bình hóa chất ướt.",en:"Cooking oil and fat fires under ISO 3941, requiring wet chemical extinguishers."},{term:"Sprinkler",vi:"Hệ thống chữa cháy tự động bằng đầu phun nước kích hoạt theo nhiệt độ.",en:"Automatic water suppression system with heat-activated heads."},{term:"Họng nước trong nhà",vi:"Điểm lấy nước chữa cháy gắn vòi, lăng phun đặt trong công trình.",en:"Indoor fire hydrant outlets with hoses and nozzles inside the building."},{term:"Impairment",vi:"Tình trạng hệ thống PCCC tạm ngừng hoạt động, phải có quy trình kiểm soát và canh cháy.",en:"A fire system out of service, requiring control procedures and a fire watch."},{term:"Phương án chữa cháy",vi:"Tài liệu kế hoạch tổ chức chữa cháy, sơ tán và phối hợp lực lượng tại cơ sở.",en:"The facility plan for firefighting, evacuation and coordination of responders."}],quiz:[{q:{vi:"Đám cháy chảo chiên ngập dầu ăn trong bếp thuộc loại nào theo ISO 3941?",en:"A deep fryer cooking oil fire belongs to which ISO 3941 class?"},options:{vi:["Loại A","Loại B","Loại C","Loại F"],en:["Class A","Class B","Class C","Class F"]},answer:3,explain:{vi:"Dầu mỡ nấu ăn là loại F, cần bình hóa chất ướt; phun nước gây bùng cháy dữ dội.",en:"Cooking oils and fats are class F and need wet chemical; water causes violent flare-ups."}},{q:{vi:"Sprinkler 0.08 L/s.m2 trên 150 m2 trong 30 phút cần bao nhiêu m3 nước?",en:"Sprinklers at 0.08 L/s.m2 over 150 m2 for 30 minutes need how much water?"},options:{vi:["12 m3","21.6 m3","43.2 m3","7.2 m3"],en:["12 m3","21.6 m3","43.2 m3","7.2 m3"]},answer:1,explain:{vi:"Lưu lượng 0.08 x 150 = 12 L/s; 12 x 1800 giây = 21600 L = 21.6 m3.",en:"Flow 0.08 x 150 = 12 L/s; 12 x 1800 s = 21600 L = 21.6 m3."}},{q:{vi:"Quản lý yêu cầu khóa van sprinkler vì hay phun nhầm. Bạn làm gì?",en:"The manager asks you to close a sprinkler valve because of false discharges. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và cho kiểm tra nguyên nhân phun nhầm","Khóa van đến khi khai trương xong","Khóa van ban ngày, mở ban đêm","Tháo đầu phun ở khu hay phun"],en:["Refuse, report in writing and have the cause investigated","Close it until after the opening","Close it by day, open at night","Remove the heads that discharge"]},answer:0,explain:{vi:"Vô hiệu hóa sprinkler khiến khu đông người mất bảo vệ; phải xử lý nguyên nhân theo quy trình.",en:"Disabling sprinklers leaves a crowded area unprotected; fix the cause through proper procedures."}},{q:{vi:"Khi chuông báo cháy kêu trong trung tâm thương mại, hướng dẫn sơ tán đúng là gì?",en:"When the fire alarm sounds in a mall, what is the correct evacuation guidance?"},options:{vi:["Dùng thang máy cho nhanh","Quay lại lấy đồ cá nhân","Đi theo lối thoát nạn, dùng thang bộ, không dùng thang máy","Chờ trong cửa hàng đến khi có thông báo"],en:["Use the lifts to be quick","Go back for belongings","Follow escape routes and stairs, never the lifts","Wait in the shop for an announcement"]},answer:2,explain:{vi:"Thang máy có thể dừng hoặc mở ra tầng cháy; phải sơ tán theo lối thoát nạn và thang bộ.",en:"Lifts may stop or open onto the fire floor; evacuate via escape routes and stairs."}}],tools_en:["Addressable fire alarm control panel","Fire protection maintenance software","Fire extinguishers (foam, CO2, wet chemical)","Fire pumps and pressure test gauges","Evacuation simulation software","Two-way radios and voice evacuation system"]}}})})(window.KKR);
